{
  "headline": "FDA's records trace our supply to a plant classified OAI 622 days before the shortage posting",
  "headline_cites": ["D11"],
  "sentences": [
    {
      "text": "FDA first posted the bupivacaine hydrochloride shortage on 2018-02-20 and it remains current as of 2026-10-21.",
      "cites": ["E54", "D25"]
    },
    {
      "text": "The shortage list includes Hospira, Inc., a Pfizer Company, among other manufacturers.",
      "cites": ["E49"]
    },
    {
      "text": "Our Corvale Lakeside and Corvale General sites hold Hospira-labeled 2.5 mg/mL 10 mL vials (NDC 00409115901) linked to label set 02a845c3.",
      "cites": ["E6", "E8", "E22"]
    },
    {
      "text": "Label 02a845c3 names Hospira, Inc. plants at FEI 1021343 and FEI 1925262 as registered manufacturing sites.",
      "cites": ["E22", "E34"]
    },
    {
      "text": "FDA inspection 976095 at FEI 1925262 ended 2016-06-08 with an OAI classification, 622 days before the shortage posting.",
      "cites": ["D11", "E28"]
    },
    {
      "text": "A Warning Letter was issued to FEI 1925262 on 2017-02-14, 371 days before the posting.",
      "cites": ["D12", "E33"]
    },
    {
      "text": "The highest-ranked mitigation is to transfer 19 vials of 2.5 mg/mL 10 mL from Corvale Lakeside to Corvale East, raising East's coverage from 4.6 to 6 days while Lakeside retains two weeks.",
      "cites": ["D26"]
    }
  ]
}
